import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"PR Routing & Approval","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/pr-routing.md","filePath":"zh/products/ai-coding/cursor/pr-routing.md","lastUpdated":1787107158000}'),i={name:"zh/products/ai-coding/cursor/pr-routing.md"};function n(s,t,l,d,p,g){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="pr-routing-approval" tabindex="-1">PR Routing &amp; Approval <a class="header-anchor" href="#pr-routing-approval" aria-label="Permalink to &quot;PR Routing &amp; Approval&quot;">​</a></h1><p>PR Routing &amp; Approval 按所有权和提交历史<strong>把 PR 派给对的审人</strong>，并在满足你的条件时<strong>批准低风险改动</strong>。它跑在 Automations 上。它<strong>不替代完整 code review</strong>。</p><blockquote><p>官方：<a href="https://cursor.com/docs/approval-agents" target="_blank" rel="noreferrer">PR Routing &amp; Approval</a>。配置入口：<a href="https://cursor.com/automations/from-cursor/pr-routing-and-approval" target="_blank" rel="noreferrer">Automations</a>。</p><p>政策文件：文件名必须精确为 <strong><code>APPROVAL_POLICY.md</code></strong>，外加可选的 <code>.cursor/approval-policies/ROUTING.md</code>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>关心的组织 / 仓库已接源代码托管</li><li>团队管理员才能<strong>编辑</strong>这条 Automation（非管理员只能看）</li><li>可选：要在决策里读 finding，就先开 Bugbot 和 / 或 <a href="./security-agents.html">Security Agents</a></li><li>Security Review Context 需要 Security Agents，且计划是 <strong>team 或 enterprise</strong></li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本页你能：</p><ol><li>分别打开「派审人」和「自动批准」</li><li>在对的目录放下受信任的 <code>APPROVAL_POLICY.md</code></li><li>知道哪些文件名会被<strong>忽略</strong></li><li>明白「同一个 PR 里改政策来放宽审查」不会生效</li></ol><hr><h2 id="它做什么" tabindex="-1">它做什么 <a class="header-anchor" href="#它做什么" aria-label="Permalink to &quot;它做什么&quot;">​</a></h2><p>Agent 根据<strong>代码所有权和提交历史</strong>指定审人。能否批准，要同时看你的 <strong>approval criteria</strong>、<strong>风险设置</strong>、<strong>政策文件</strong>、<strong>AI 审查 finding</strong> 和<strong>当前审查状态</strong>。</p><p>两项能力分开开：</p><table tabindex="0"><thead><tr><th>能力</th><th>官方开关</th><th>干什么</th></tr></thead><tbody><tr><td>派审人</td><td><strong>Enable PR Routing and Requests for Review</strong></td><td>请求审人</td></tr><tr><td>按风险批准</td><td><strong>Automatically Approve PRs</strong></td><td>配好标准后才批准</td></tr></tbody></table><h2 id="它能读的信号" tabindex="-1">它能读的信号 <a class="header-anchor" href="#它能读的信号" aria-label="Permalink to &quot;它能读的信号&quot;">​</a></h2><h3 id="ai-审查感知" tabindex="-1">AI 审查感知 <a class="header-anchor" href="#ai-审查感知" aria-label="Permalink to &quot;AI 审查感知&quot;">​</a></h3><ul><li><strong>Bugbot Review Context</strong> — Bugbot finding 进入批准决策</li><li><strong>Security Review Context</strong> — Security Agent finding 进入批准决策</li></ul><p>打开后，Agent <strong>会等</strong>这些检查跑完。若 Bugbot 或 Security Agents 报告了需要人看的 finding，PR Routing <strong>不会批准</strong>。</p><p>Security Agents 需要 <strong>team 或 enterprise</strong> 计划。</p><h3 id="风险打分" tabindex="-1">风险打分 <a class="header-anchor" href="#风险打分" aria-label="Permalink to &quot;风险打分&quot;">​</a></h3><ul><li><strong>Use Risk Score</strong> — 给 PR 分风险（可用 prompting 再定制）</li><li><strong>Maximum Risk Threshold</strong> — Agent 最多能批到哪一档</li></ul><p>超过阈值就不会批。</p><h2 id="政策文件" tabindex="-1">政策文件 <a class="header-anchor" href="#政策文件" aria-label="Permalink to &quot;政策文件&quot;">​</a></h2><h3 id="approval-policy-md" tabindex="-1"><code>APPROVAL_POLICY.md</code> <a class="header-anchor" href="#approval-policy-md" aria-label="Permalink to &quot;`APPROVAL_POLICY.md`&quot;">​</a></h3><p>对每个被改的文件，Agent 从该文件所在目录往上走，找这个<strong>精确</strong>文件名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APPROVAL_POLICY.md</span></span></code></pre></div><p>只信任精确 basename。下面这些会被<strong>忽略</strong>：</p><ul><li><code>POLICY.md</code></li><li><code>approval_policy.md</code></li><li><code>APPROVAL_POLICY.md.bak</code></li><li><code>team_APPROVAL_POLICY.md</code></li></ul><p><strong>最近</strong>的那份优先级最高。祖先目录的政策仍然生效，除非和更具体的一份冲突。</p><h3 id="cursor-approval-policies-routing-md" tabindex="-1"><code>.cursor/approval-policies/ROUTING.md</code> <a class="header-anchor" href="#cursor-approval-policies-routing-md" aria-label="Permalink to &quot;`.cursor/approval-policies/ROUTING.md`&quot;">​</a></h3><p>顶层路由文件。YAML 列表，每项一个产品：</p><ul><li><code>product</code> — 产品或区域名</li><li><code>boundary</code> — 语义边界，或相对仓库的路径 / glob</li><li><code>policies</code> — 政策提示指针（路径或语义描述）</li></ul><p>没有 <code>ROUTING.md</code> 时，基于目录的 <code>APPROVAL_POLICY.md</code> 发现<strong>仍会跑</strong>。缺路由不会削弱政策发现。</p><h3 id="优先级" tabindex="-1">优先级 <a class="header-anchor" href="#优先级" aria-label="Permalink to &quot;优先级&quot;">​</a></h3><p>适用的 approval policy 提示会覆盖通用批准标准、风险阈值、选审人指引、自定义批准指令，以及默认的自动审查姿态。</p><p>政策冲突：跟<strong>最具体</strong>的。说不清谁更具体：跟<strong>更严</strong>的，并<strong>避免自动批准</strong>。</p><p>若某个 PR <strong>改了</strong> approval policy、路由文件、被路由到的政策文件或审人专用政策文件，Agent <strong>不会</strong>用这次改过的内容给<strong>同一个 PR</strong> 放宽审查。能拿到就用 <strong>base 分支</strong>上的版本，否则要求人审。</p><p>最小示例（只示范形状 — 规则写成你们团队真正要的）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># APPROVAL_POLICY.md  （例如只放在 docs/）</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">本目录的错字和文案修改可以自动批准。</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">任何碰到鉴权、计费或依赖版本的改动，必须有人审。</span></span></code></pre></div><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>打开 <a href="https://cursor.com/automations/from-cursor/pr-routing-and-approval" target="_blank" rel="noreferrer">Automations 里的 PR Routing &amp; Approval</a>。</p><ol><li>打开路由和 / 或自动批准</li><li>选组织和仓库</li><li>配 <strong>triggers</strong>： <ul><li><strong>PR opened</strong></li><li><strong>PR pushed / updated</strong></li><li><strong>PR commented</strong>（评论匹配正则）</li></ul></li><li>在 <strong>Configuration</strong> 里选信号：Bugbot 上下文、Security 上下文、风险分、最高风险</li><li>可选 <strong>Custom Prompt</strong> 写团队预期。适用文件仍以政策文件为准。空着就用 Cursor 托管默认</li><li>工具：Agent <strong>至少要有一个</strong>主动作 — <strong>Request Reviewers</strong> 和 / 或 <strong>Approve PR</strong>。可选：Slack、Microsoft Teams、额外 MCP</li><li>保存。之后在详情页开关</li></ol><p>触发器可以按仓或按组织收窄。团队管理员可以配更宽的团队范围。</p><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><ul><li>大 monorepo：按所有权把 PR 派给对的人</li><li>低风险文档 / 生成文件：只在 <code>APPROVAL_POLICY.md</code> 允许的地方自动批</li><li>和 Bugbot + Security Agents 一起：自动批准要<strong>等</strong>这些 finding</li></ul><p>鉴权、支付、以及政策标成禁区的东西，继续人审。这个产品<strong>不替代</strong>那一步。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td><code>approval_policy.md</code> 或 <code>POLICY.md</code></td><td>精确名字 <strong><code>APPROVAL_POLICY.md</code></strong></td></tr><tr><td>以为没有 <code>ROUTING.md</code> 政策就不跑</td><td>目录发现仍会跑</td></tr><tr><td>同一个 PR 里改政策来放宽</td><td>Agent 用 <strong>base 分支</strong>副本，或要求人审</td></tr><tr><td>开了自动批准却没开主动作</td><td>需要 <strong>Approve PR</strong>（和 / 或 <strong>Request Reviewers</strong>）</td></tr><tr><td>无视 Bugbot / Security finding</td><td>这些上下文开着且需要人看时，<strong>不会自动批</strong></td></tr><tr><td>当成 Bugbot</td><td>Bugbot 留言；这个<strong>派审人，并可能批准</strong></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./security-agents.html">Security Agents</a> — Security Review Context</li><li><a href="./cursor-cookbook.html#用-bugbot-审-pr">Cookbook · Bugbot</a> — Bugbot Review Context</li><li><a href="./cloud-agents.html">Cloud Agents</a> — Automations 跑的是 Cloud Agents</li><li>官方：<a href="https://cursor.com/docs/approval-agents" target="_blank" rel="noreferrer">PR Routing &amp; Approval</a>、<a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></li></ul>',49)])])}const P=o(i,[["render",n]]);export{b as __pageData,P as default};
